    /* ---------- Global - Xe 4-5 Chỗ ---------- */
    "global-supreme-4-5-cho": { name: "Global Supreme Series (Xe 4-5 Chỗ)", brand: "Global", price: "13.200.000₫", desc: "Phim cách nhiệt Global dòng Supreme Series, thương hiệu Mỹ hơn 50 năm kinh nghiệm, công nghệ siêu co liên kết chéo và chống tĩnh điện, lớp phủ chống xước gấp đôi phim thường. Cản UV 99%, cản hồng ngoại 96%. Trọn gói dán cho xe 4-5 chỗ. Hàng chính hãng Global - phân phối bởi AKauto.", specs: [["Dòng phim","Global Supreme (50/40/15/05)"],["Cản tia UV","99%"],["Cản tia hồng ngoại","96%"],["Độ truyền sáng","6-49% (tùy mã phim)"],["Tiêu chuẩn","ISO-9001:2008"],["Bảo hành","Trọn đời"],["Dòng xe áp dụng","Xe 4-5 chỗ"],["Xuất xứ","Chính hãng Global (Mỹ) - phân phối bởi AKauto"]] },
    "global-qdp-ceramic-4-5-cho": { name: "Global QDP Ceramic Series (Xe 4-5 Chỗ)", brand: "Global", price: "6.300.000₫", desc: "Phim cách nhiệt Global dòng QDP Ceramic Series, lựa chọn tiết kiệm hơn trong danh mục Global Window Films, vẫn đảm bảo cản nhiệt và bảo vệ nội thất hiệu quả. Trọn gói dán cho xe 4-5 chỗ. Hàng chính hãng Global - phân phối bởi AKauto.", specs: [["Dòng phim","Global QDP Ceramic (50) / NF Charcoal 20 / NF Grey 20"],["Bảo hành","Trọn đời"],["Tiêu chuẩn","ISO-9001:2008"],["Dòng xe áp dụng","Xe 4-5 chỗ"],["Xuất xứ","Chính hãng Global (Mỹ) - phân phối bởi AKauto"]] },

